package main

import (
	"errors"
	"fmt"
)

// 1) 参数立即求值 vs 闭包捕获：Go 1.22 per-iteration 语义
func loopDefer() {
	for i := 0; i < 3; i++ {
		defer fmt.Println("arg:", i)              // 参数立即求值，注册时拷贝：输出 2,1,0
		defer func() { fmt.Println("clo:", i) }() // Go 1.22+ per-iteration：也输出 2,1,0
	}
	// Go 1.21 及更早 go.mod 下闭包形式输出三个 3

	var j int
	for ; j < 3; j++ {
		defer func() { fmt.Println("outer:", j) }() // 捕获循环外变量，j 不受 per-iteration 影响
	}
}

// 2) 命名返回值：defer 里能修改返回值
func readConfig() (cfg string, err error) {
	defer func() {
		if err != nil {
			err = fmt.Errorf("readConfig: %w", err) // 命名返回值，改的是同一个栈槽
		}
	}()
	return "", errors.New("file not found")
}

// 3) recover 包一层 helper 就失效
type appError struct{ msg string }

func (e *appError) Error() string { return e.msg }

func badRecover() {
	defer logRecover() // helper 里 recover() 的 sp 跟 _defer.sp 不匹配，永远返回 nil
	panic(&appError{msg: "won't be caught"})
}
func logRecover() {
	if r := recover(); r != nil {
		fmt.Println("caught:", r)
	}
}

// 4) 正确模板：recover 直接在 deferred 函数体，sp 匹配才生效
func safeRun(fn func()) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("panic: %v", r)
		}
	}()
	fn()
	return nil
}

// 5) 跨 goroutine panic：每个 go func() 必须自己 defer recover
func spawn() {
	go func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Println("child caught:", r)
			}
		}() // 没这一行，子 goroutine panic 直接 fatalpanic 终止进程
		panic("in child")
	}()
}

// 6) 循环里 defer 的正确替代：抽子函数
func closeAll(files []string) error {
	for _, name := range files {
		if err := openAndClose(name); err != nil {
			return err
		}
	}
	return nil
}
func openAndClose(name string) (err error) {
	// defer 在子函数返回时执行，fd 及时释放
	f, err := osOpen(name)
	if err != nil {
		return err
	}
	defer func() {
		if cerr := f.Close(); cerr != nil && err == nil {
			err = cerr
		}
	}()
	return nil
}

func osOpen(name string) (*osFile, error) { return &osFile{name: name}, nil }

type osFile struct{ name string }

func (f *osFile) Close() error { return nil }

func main() {
	loopDefer()
	_, _ = readConfig()
	badRecover()
	_ = safeRun(func() { panic("recovered") })
	spawn()
}
